<?php
require_once __DIR__ . '/../includes/db.php'; require_admin(); $page_title='Manage Returns'; $returns=$pdo->query("SELECT r.*,i.item_name,u.name AS renter_name FROM `returns` r INNER JOIN items i ON i.item_id=r.item_id INNER JOIN users u ON u.user_id=r.renter_id ORDER BY r.created_at DESC")->fetchAll(); require_once __DIR__ . '/../includes/header.php'; require __DIR__ . '/_nav.php';
?>
<h1 class="h3 mb-4">Returns</h1><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-light"><tr><th class="ps-3">Item / Renter</th><th>Return Date</th><th>Condition</th><th>Late Fee</th><th class="pe-3">Status</th></tr></thead><tbody><?php foreach($returns as $return): ?><tr><td class="ps-3"><?php echo e($return['item_name']); ?><div class="small text-muted"><?php echo e($return['renter_name']); ?></div></td><td><?php echo e($return['return_date']); ?></td><td><?php echo e($return['return_condition']); ?></td><td><?php echo e(format_money($return['late_fee'])); ?></td><td class="pe-3"><span class="badge text-bg-<?php echo e(status_badge_class($return['return_status'])); ?>"><?php echo e($return['return_status']); ?></span></td></tr><?php endforeach; ?></tbody></table></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
